def create_initial_arena_data(apps, schema_editor):
    """
    新闘技場の初期データを作成する。

    ・1～100階のArenaFloor
    ・既存キャラクター全員のArenaState

    を作成する。
    """

    Character = apps.get_model(
        "accounts",
        "Character",
    )

    ArenaFloor = apps.get_model(
        "battle",
        "ArenaFloor",
    )

    ArenaState = apps.get_model(
        "battle",
        "ArenaState",
    )

    db_alias = schema_editor.connection.alias

    # ========================================
    # 1～100階を作成
    # ========================================

    ArenaFloor.objects.using(
        db_alias
    ).bulk_create(
        [
            ArenaFloor(
                floor=floor,
            )
            for floor in range(1, 101)
        ],
        ignore_conflicts=True,
    )

    # ========================================
    # 既存キャラクターを1階へ配置
    # ========================================

    existing_character_ids = set(
        ArenaState.objects.using(
            db_alias
        ).values_list(
            "character_id",
            flat=True,
        )
    )

    states = []

    for character in (
        Character.objects.using(
            db_alias
        ).all()
    ):

        if character.id in existing_character_ids:
            continue

        states.append(
            ArenaState(
                character_id=character.id,

                # 全員1階スタート
                floor_id=1,

                # 闘技場HP / MPは満タンから開始
                current_hp=character.max_hp,
                current_mp=character.max_mp,
            )
        )

    ArenaState.objects.using(
        db_alias
    ).bulk_create(
        states
    )


